def transform(grid):
    result = [row[:] for row in grid]
    for r in range(len(grid)):
        row = grid[r]
        primary_cols = [c for c in range(len(row)) if row[c] in [1, 5]]
        if not primary_cols:
            continue
        min_col, max_col = min(primary_cols), max(primary_cols)
        for c in range(len(row)):
            if row[c] in [0, 4] and min_col < c < max_col:
                result[r][c] = 2
    return result

